INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(52211, 'Exodus 3:9', 'Exodus', 3, 9, 'زما قوم ماته د مرستې دپاره زارۍ کولې او ما لیدلي دي چې مصریان په هغوی باندې څومره ظلم کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus3_verse_9.mp3', '', 1761754199, 1761754199),
(52212, 'Exodus 3:10', 'Exodus', 3, 10, 'اوس فرعون ته ورشه! زه تا هلته لېږم، ترڅو زما قوم یعنې اسراییلیان له هغې خاورې څخه راوباسې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus3_verse_10.mp3', '', 1761754199, 1761754199),
(52213, 'Exodus 3:11', 'Exodus', 3, 11, 'خو موسی خدای ته وویل: «زه څوک یم چې فرعون ته ورشم او اسراییلیان له مصر څخه وباسم؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus3_verse_11.mp3', '', 1761754199, 1761754199),
(52214, 'Exodus 3:12', 'Exodus', 3, 12, 'خدای په ځواب کې وویل: «زه به ستا سره مل یم. او دا به تاته یوه نښه وي چې دا زه یم چې ته مې ولېږلې: کله چې ته د اسراییلو قوم د مصر څخه راوباسې، تاسو به په دې غره باندې د خدای عبادت وکړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus3_verse_12.mp3', '', 1761754199, 1761754199),
(52215, 'Exodus 3:13', 'Exodus', 3, 13, 'موسی خدای ته وویل: «کله چې زه اسراییلیانو ته ورشم او هغوی ته ووایم چې زه ستاسو د نیکونو خدای رالېږلی یم، هغوی به زما څخه ستا د نوم پوښتنه وکړي، نو زه هغوی ته څه ځواب ورکړم؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus3_verse_13.mp3', '', 1761754199, 1761754199),
(52216, 'Exodus 3:16', 'Exodus', 3, 16, 'لاړ شه او د اسراییلو مشران سره راټول کړه او ورته ووایه چې څښتن ستاسو د نیکونو یعنې ابراهیم، اسحاق او د یعقوب خدای ماته راښکاره شو. هغوی ته ووایه چې زه تاسو ته راغلی یم او لیدلي مې دي چې مصریان تاسو سره څومره بد چلند کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus3_verse_16.mp3', '', 1761754199, 1761754199),
(52217, 'Exodus 3:17', 'Exodus', 3, 17, 'زه دا وعده کوم چې تاسو به د مصر د تکلیفونو څخه خلاص کړم. او زه به تاسو ته غني او حاصلخېزه ځمکه درکړم چېرته چې کنعانیان، حیتیان، اموریان، فرزیان، حویان او یبوسیان اوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus3_verse_17.mp3', '', 1761754199, 1761754199),
(52218, 'Exodus 3:18', 'Exodus', 3, 18, 'د اسراییلو مشران به ستا خبرو ته غوږ کېږدي. بیا هغوی د مصر پاچا ته وروله او ورته ووایئ: د عبرانیانو څښتن خدای مونږ ته راښکاره شوی دی. مونږ پرېږده چې په دښته کې درې ورځې سفر وکړو چې هغه ته قربانۍ وړاندې کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus3_verse_18.mp3', '', 1761754199, 1761754199),
(52219, 'Exodus 3:19', 'Exodus', 3, 19, 'زه پوهېږم چې د مصر پاچا به تاسو پرېنږدي چې لاړ شئ، ترڅو چې هغه مجبور نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus3_verse_19.mp3', '', 1761754199, 1761754199),
(52220, 'Exodus 3:20', 'Exodus', 3, 20, 'نو زه به د خپل قدرت څخه کار واخلم او مصریانو ته به په هر ډول معجزو باندې سزا ورکړم. له هغې وروسته به هغه تاسو پرېږدي چې لاړ شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus3_verse_20.mp3', '', 1761754199, 1761754199),
(52221, 'Exodus 3:21', 'Exodus', 3, 21, 'زه به مصریان دې ته مجبور کړم چې ستاسو عزت وکړي، نو کله چې زما قوم ځي، هغوی به خالي لاس نه ځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus3_verse_21.mp3', '', 1761754199, 1761754199),
(52222, 'Exodus 3:22', 'Exodus', 3, 22, 'هره اسراییلۍ ښځه به خپلې مصرۍ ګاونډۍ یا بلې مصرۍ ښځې ته چې د هغې په کور کې اوسیږي، ورشي او د هغې څخه به د سرو او سپینو زرو زېورات او کالي واخلي او خپلو لورګانو او زامنو ته به یې واغوندي. کله چې د مصر څخه وځئ، نو د مصریانو شتمني به د ځان سره یوسئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus3_verse_22.mp3', '', 1761754199, 1761754199),
(52223, 'Psalms 81:1', 'Psalms', 81, 1, 'خدای ته سندرې د خوښۍ ووایئ چې دی قوت زمونږه د خوشحالۍ ووهئ چیغې د یعقوب خدای ته!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms81_verse_1.mp3', '', 1761754199, 1761754199),
(52224, 'Psalms 81:2', 'Psalms', 81, 2, 'سازونه پیل کړئ او چمبې ووهئ وغږوئ د خوشحالۍ ساز په ربابونو او چنګونو سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms81_verse_2.mp3', '', 1761754199, 1761754199),
(52225, 'Psalms 81:3', 'Psalms', 81, 3, 'د اختر دپاره ووهئ سرنی په هغه وخت کې چې شي میاشت نوې او په داسې وخت کې چې پوره شي سپوږمۍ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms81_verse_3.mp3', '', 1761754199, 1761754199),
(52226, 'Psalms 81:4', 'Psalms', 81, 4, 'دا یو قانون دی اسراییلو کې دا دی یو حکم د یعقوب د خدای', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms81_verse_4.mp3', '', 1761754199, 1761754199),
(52227, 'Psalms 81:5', 'Psalms', 81, 5, 'هغه جوړ کړ یو قانون یوسف دپاره چې کله یې وکړه حمله د مصر خاوره باندې یو نا‌اشنا اواز مې واورېد چې ویل یې داسې:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms81_verse_5.mp3', '', 1761754199, 1761754199),
(52228, 'Psalms 81:6', 'Psalms', 81, 6, '«ستاسو اوږو نه مې اوچت کړل درانه بارونه او تاسو مې خلاص کړئ له درندو کارونو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms81_verse_6.mp3', '', 1761754199, 1761754199),
(52229, 'Psalms 81:7', 'Psalms', 81, 7, 'کله چې تاسو وئ تکلیف کې اخته ومو کړ ماته فریاد او تاسو مې وژغورلئ له تندریځې ورېځې در مې کړ ځواب درته ومې ازمایلئ تاسو د مریبه د چینو څنګ کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms81_verse_7.mp3', '', 1761754199, 1761754199),
(52230, 'Psalms 81:8', 'Psalms', 81, 8, 'ای زما قومه واورئ زه درکومه اخطار! ای اسراییلو کاشکې تاسو ماته غوږ ونیسئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms81_verse_8.mp3', '', 1761754199, 1761754199),
(52231, 'Psalms 81:9', 'Psalms', 81, 9, 'پردی خدای دې ستاسو منځ کې نه وي سجده ونه کړئ بېګانه خدای ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms81_verse_9.mp3', '', 1761754199, 1761754199),
(52232, 'Psalms 81:10', 'Psalms', 81, 10, 'زه څښتن خدای یم ستاسو چې مې د مصر نه راوویستلئ خلاصې مو خولې کړئ زه به ماړه کړم تاسو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms81_verse_10.mp3', '', 1761754199, 1761754199),
(52233, 'Psalms 81:11', 'Psalms', 81, 11, 'خو زما قوم ماته غوږ ونه نیوه او اطاعت ونه کړ اسراییلیانو زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms81_verse_11.mp3', '', 1761754199, 1761754199),
(52234, 'Psalms 81:12', 'Psalms', 81, 12, 'نو ځکه پرېښودل مې دوی د خپل سخت زړه عملونو لره چې وي روان په خواهشاتو د نفسونو پسې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms81_verse_12.mp3', '', 1761754199, 1761754199),
(52235, 'Psalms 81:13', 'Psalms', 81, 13, 'کاشکې خپل قوم مې راته غوږ ونیسي اسراییل کاشکې زما په لاره لاړ شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms81_verse_13.mp3', '', 1761754199, 1761754199),
(52236, 'Psalms 81:14', 'Psalms', 81, 14, 'زه به زر ماتې ورکړم د هغوی دښمن ته او رقیبانو د هغوی باندې به پورته کړم خپل لاس', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms81_verse_14.mp3', '', 1761754199, 1761754199),
(52237, 'Psalms 81:15', 'Psalms', 81, 15, 'چا چې نفرت کاوه له ما نه زما په مخکې به ټیټ کړي سرونه خپل له وېرې ځینې دوی تر ابده به سزا وویني', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms81_verse_15.mp3', '', 1761754199, 1761754199),
(52238, 'Psalms 81:16', 'Psalms', 81, 16, 'خو تاسو ته به درکړم د ښو غنمو خوراک او تاسو ماړه به کړمه د ځنګل په شاتو»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms81_verse_16.mp3', '', 1761754199, 1761754199),
(52239, 'Job 19:1', 'Job', 19, 1, 'بيا ايُوب جواب ورکړو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_1.mp3', '', 1761754199, 1761754199),
(52240, 'Job 19:2', 'Job', 19, 2, '”تۀ به تر کومې پورې ما له تکليف راکوې، او په خپلو خبرو به زما زړۀ غوڅوې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_2.mp3', '', 1761754199, 1761754199),
(52241, 'Job 19:3', 'Job', 19, 3, 'تا لس ځلې زما بې‌عزتى کړې ده، تۀ چې ما له کوم تکليف راکوې په هغې تۀ شرمېږې نۀ څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_3.mp3', '', 1761754199, 1761754199),
(52242, 'Job 19:4', 'Job', 19, 4, 'او کۀ دا رښتيا هم وى چې ما غلطى کړې ده، نو ستا په کښې څۀ کار دے؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_4.mp3', '', 1761754199, 1761754199),
(52243, 'Job 19:5', 'Job', 19, 5, 'تۀ په خپل نظر کښې زما نه لوئ يې، زما تکليف د ګناه د ثبوت دپاره استعمالوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_5.mp3', '', 1761754199, 1761754199),
(52244, 'Job 19:6', 'Job', 19, 6, 'نو بيا پوهه شه چې خُدائ پاک زۀ په غلطه کړے يم، او زما نه ګېرچاپېره يې جال خور کړے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_6.mp3', '', 1761754199, 1761754199),
(52245, 'Job 19:7', 'Job', 19, 7, 'ګوره، زۀ د فرياد چغې هم وهم، خو څوک ما له جواب نۀ شى راکولے، زۀ په زوره زوره چغې وهم، خو اِنصاف نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_7.mp3', '', 1761754199, 1761754199),
(52246, 'Job 19:8', 'Job', 19, 8, 'خُدائ پاک زما لارې بندې کړې دى او زۀ خوځېدے نۀ شم، او هغۀ زما په لار کښې تيارې جوړې کړې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_8.mp3', '', 1761754199, 1761754199),
(52247, 'Job 19:9', 'Job', 19, 9, 'هغۀ زما نه عزت اخستے دے، او زما د سر نه يې تاج اخوا کړے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_9.mp3', '', 1761754199, 1761754199),
(52248, 'Job 19:10', 'Job', 19, 10, 'هغه د هر طرف نه ما راغورزوى او زۀ ختم يم، هغۀ د ونې په شان زما د اُميد جرړې راويستلې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_10.mp3', '', 1761754199, 1761754199),
(52249, 'Job 19:11', 'Job', 19, 11, 'هغه زما خِلاف سخت غصه شوے دے، او هغه مې خپل دشمن ګڼى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_11.mp3', '', 1761754199, 1761754199),
(52250, 'Job 19:12', 'Job', 19, 12, 'د هغۀ فوجيان راغونډ شوى دى، هغوئ په ما باندې حملې دپاره لارې تيارې کړې دى. او زما د خېمې نه ګېرچاپېره يې خېمې لګولې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_12.mp3', '', 1761754199, 1761754199),
(52251, 'Job 19:13', 'Job', 19, 13, 'زما خپلوان ما نه ځان لرې ساتى، او زما دوستان زما خلاف شوى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_13.mp3', '', 1761754199, 1761754199),
(52252, 'Job 19:14', 'Job', 19, 14, 'زما خپلوانو او زما نزدې دوستانو زۀ پرېښے او هېر کړے يم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_14.mp3', '', 1761754199, 1761754199),
(52253, 'Job 19:15', 'Job', 19, 15, 'زما په کور کښې مېلمنو زۀ هېر کړے يم، زما وينځې ما پردے سړے ګڼى، زۀ د هغوئ په نظر کښې يو مسافر يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_15.mp3', '', 1761754199, 1761754199),
(52254, 'Job 19:16', 'Job', 19, 16, 'زۀ چې خپل نوکر راوغواړم نو هغه ما له نۀ راځى، زۀ هغۀ ته سوال زارى کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_16.mp3', '', 1761754199, 1761754199),
(52255, 'Job 19:17', 'Job', 19, 17, 'زما د خولې بوئ هم زما په ښځه باندې بد لګى، زما خپل خاندان زما نه نفرت کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_17.mp3', '', 1761754199, 1761754199),
(52256, 'Job 19:18', 'Job', 19, 18, 'واړۀ ماشومان هم ما ته سپک ګورى، کله چې زۀ هغوئ سره خبرې کول غواړم نو هغوئ ما ته شا کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_18.mp3', '', 1761754199, 1761754199),
(52257, 'Job 19:19', 'Job', 19, 19, 'زما نزدې ملګرى زما نه نفرت کوى، او چې د چا سره ما مينه کوله نو هغوئ زما نه مخ اړولے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_19.mp3', '', 1761754199, 1761754199),
(52258, 'Job 19:20', 'Job', 19, 20, 'په ما کښې صرف هډوکى او څرمن پاتې دى او ډېر په مشکله د مرګ نه تښتېدلے يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_20.mp3', '', 1761754199, 1761754199),
(52259, 'Job 19:21', 'Job', 19, 21, 'اے زما دوستانو، په ما باندې رحم وکړئ، په ما باندې رحم وکړئ، ځکه چې د خُدائ پاک ګزار زۀ وهلے يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_21.mp3', '', 1761754199, 1761754199),
(52260, 'Job 19:22', 'Job', 19, 22, 'تاسو د خُدائ پاک په شان ولې ما پسې يئ، تاسو زۀ ښۀ نۀ يم کړولے څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_22.mp3', '', 1761754199, 1761754199),
(52261, 'Job 19:23', 'Job', 19, 23, 'کاش چې زما خبرې ليکلے شوے وے، کاش چې زما خبرې په يو کِتاب کښې بيان شوے وے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_23.mp3', '', 1761754199, 1761754199),
(52262, 'Job 19:24', 'Job', 19, 24, 'کاش چې د اوسپنې او د پيتلو د قلم سره دا خبرې په يو ګټ باندې د تل دپاره نقش شوے وے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_24.mp3', '', 1761754199, 1761754199),
(52263, 'Job 19:25', 'Job', 19, 25, 'زما يقين دے چې زما خلاصونکے ژوندے دے، او چې په آخر کښې به هغه د زمکې دپاسه ودريږى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_25.mp3', '', 1761754199, 1761754199),
(52264, 'Job 19:26', 'Job', 19, 26, 'او چې کله زما څرمن بلکل ختمه شى، نو بيا به زۀ په خپلو سترګو خُدائ پاک ووينم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_26.mp3', '', 1761754199, 1761754199),
(52265, 'Job 19:27', 'Job', 19, 27, 'زۀ به هغه په خپله وګورم، او زۀ به هغه په خپلو سترګو ووينم. ما سره صرف هم دغه فکر دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_27.mp3', '', 1761754199, 1761754199),
(52266, 'Job 19:28', 'Job', 19, 28, 'ستا حق نۀ جوړيږى چې ما له تکليف راکوې، او وائې چې دا ستا خپله غلطى ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_28.mp3', '', 1761754199, 1761754199),
(52267, 'Job 19:29', 'Job', 19, 29, 'د سزا نه پخپله يرېږه ځکه چې ستا رويه د سزا لائقه ده، او بيا به تا ته پته ولګى چې حساب کِتاب شته.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job19_verse_29.mp3', '', 1761754199, 1761754199),
(52268, 'Ezekiel 47:1', 'Ezekiel', 47, 1, 'بیا هغه سړي زه د څښتن د کور دروازې ته بوتلم. ما ولیدل چې د دروازې لاندې اوبه راروانې وې او ختیځې خواته د څښتن د کور مخې ته بهېدلې، ځکه چې د کور ختیځ خواته ؤ. هغه د څښتن د کور د جنوبي برخې نه لاندې تېرېدلې او د قربانۍ د ځای جنوب خواته بهېدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel47_verse_1.mp3', '', 1761754199, 1761754199),
(52269, 'Ezekiel 47:2', 'Ezekiel', 47, 2, 'بیا هغه سړي د شمالي دروازې په لاره د څښتن د کور د ساحې نه دباندې راوویستلم او هغې باندینۍ دروازې ته یې بوتلم چې ختیځ خواته مخامخ وه. د دروازې جنوب خواته یوه کوچنۍ ویاله بهېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel47_verse_2.mp3', '', 1761754199, 1761754199),
(52270, 'Ezekiel 47:3', 'Ezekiel', 47, 3, 'هغه د اندازه کولو په لرګي باندې پنځه سوه متره ختیځې خواته کوزه ویاله اندازه کړه او ما سره یې مرسته وکړه چې د ویالې نه تېر شم. اوبه زما د پښو تر بنده پورې رسېدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel47_verse_3.mp3', '', 1761754199, 1761754199),
(52271, 'Ezekiel 47:4', 'Ezekiel', 47, 4, 'بیا هغه نور پنځه سوه متره اندازه کړه او زما سره یې مرسته وکړه چې د اوبو نه تېر شم، هلته اوبه زما تر زنګنونو پورې رسېدلې. د هغه ځای نه پنځه سوه متره لېرې اوبه زما تر ملا پورې رسېدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel47_verse_4.mp3', '', 1761754199, 1761754199),
(52272, 'Ezekiel 47:5', 'Ezekiel', 47, 5, 'هغه نور پنځه سوه متره اندازه واخیستله او په هغه ځای کې سیند ډېر ژور ؤ چې ورڅخه پورې وتلی نه شوم. دا سیند دومره ژور ؤ چې هېڅوک پرته د لامبو نه ورڅخه پورې وتلی نه شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel47_verse_5.mp3', '', 1761754199, 1761754199),
(52273, 'Ezekiel 47:6', 'Ezekiel', 47, 6, 'هغه ماته وویل: «ای فاني انسانه، دې هرڅه ته په غور سره وګوره.» بیا زه هغه سړي بېرته د سیند غاړې ته بوتلم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel47_verse_6.mp3', '', 1761754199, 1761754199),
(52274, 'Ezekiel 47:7', 'Ezekiel', 47, 7, 'او کله چې هلته ورسېدم، ما ولیدل چې د سیند دواړو غاړو ته ډېرې زیاتې ونې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel47_verse_7.mp3', '', 1761754199, 1761754199),
(52275, 'Ezekiel 47:8', 'Ezekiel', 47, 8, 'هغه ماته وویل: «دا اوبه ختیځې سیمې او لاندې مړې بحیرې ته بهیږي. کله چې دا اوبه مړې بحیرې ته وروبهیږي، نو د مړې بحیرې مالګینې اوبه په خوږو اوبو باندې بدلیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel47_verse_8.mp3', '', 1761754199, 1761754199),
(52276, 'Ezekiel 47:9', 'Ezekiel', 47, 9, 'هر چېرته چې دا سیند جاري شي، نو هلته به ډول ډول حیوانات او ډېر زیات ماهیان وي. دا سیند د مړې بحیرې اوبه خوږې کوي او چېرته چې هغه بهیږي، نو هرڅه به هلته ژوندي وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel47_verse_9.mp3', '', 1761754199, 1761754199),
(52277, 'Ezekiel 47:10', 'Ezekiel', 47, 10, 'د عین‌جدي نه تر عین‌عجلایم پورې به ماهيګیران د مړې بحیرې په غاړه ولاړ وي او په هغه ځای کې به خپل جالونه وغوړوي چې وچ شي. هلته به د مدیترانې د بحیرې په شان ډول ډول ماهیان وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel47_verse_10.mp3', '', 1761754199, 1761754199),
(52278, 'Ezekiel 47:11', 'Ezekiel', 47, 11, 'خو جبه‌زاره ډنډونه به پاک نه شي، هغه به د مالګې دپاره پاتې شي.‍', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel47_verse_11.mp3', '', 1761754199, 1761754199),
(52279, 'Ezekiel 47:12', 'Ezekiel', 47, 12, 'د سیند په دواړو غاړو باندې به هر ډول ونې راشنې کیږي چې مېوه ونیسي. د هغو پاڼې به هېڅکله نه مړاوې کیږي او تل به مېوه نیسي. هغه به هره میاشت مېوه نیسي، ځکه چې هغه ته د داسې سیند اوبه ورکول کیږي چې د عبادت د ځای نه راځي. د هغو د مېوو نه به د خوراک دپاره ګټه اخیستل کیږي او د پاڼو نه به یې د خلکو د علاج دپاره کار اخیستل کیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel47_verse_12.mp3', '', 1761754199, 1761754199),
(52280, 'Ezekiel 47:13', 'Ezekiel', 47, 13, 'څښتن تعالی داسې وویل: «دا د هېواد سرحدونه دي چې د اسراییلو په دولس قبیلو باندې به د ملکیت په توګه وېشل کیږي. د یوسف قبیلې ته به دوه برخې ورکړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel47_verse_13.mp3', '', 1761754199, 1761754199),
(52281, 'Ezekiel 47:14', 'Ezekiel', 47, 14, 'ما ستاسو د نیکونو سره قسم خوړلی ؤ چې زه به دا هېواد هغوی ته ورکړم، اوس تاسو هغه د خپل ملکیت په توګه په خپل منځ کې سره برابر ووېشئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel47_verse_14.mp3', '', 1761754199, 1761754199),
(52282, 'Ezekiel 47:15', 'Ezekiel', 47, 15, 'شمالي سرحد به ختیځې خواته د مدیترانې د بحیرې نه پیل شي او د حتلون تر ښاره، د حمات تر غاښي، د صدد تر ښاره،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel47_verse_15.mp3', '', 1761754199, 1761754199),
(52283, 'Ezekiel 47:16', 'Ezekiel', 47, 16, 'بیروته او سبرایم تر ښارونو چې دا ښارونه د دمشق د پاچاهۍ او حمات د پاچاهۍ ترمنځ پراته دي او د حاضیر‌حاتکان تر ښاره پورې چې د حوران د سیمې په سرحد باندې پروت دی، ورسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel47_verse_16.mp3', '', 1761754199, 1761754199),
(52284, 'Ezekiel 47:17', 'Ezekiel', 47, 17, 'نو شمالي سرحد به د مدیترانې د بحیرې نه ختیځې خواته د حصرعینان تر ښاره چې د دمشق په شمال او د حمات په جنوب کې دی، ورسیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel47_verse_17.mp3', '', 1761754199, 1761754199),
(52285, 'Ezekiel 47:18', 'Ezekiel', 47, 18, '«ختیځ سرحد به جنوب خواته د حورون او دمشق د دواړو پاچاهیو ترمنځ سرحد نه پیل شي، د اردن د سیند نه چې په لوېدیځ کې د اسراییلو د هېواد او په ختیځ کې د جلعاد د سیمې ترمنځ سرحد جوړوي او د تامار تر ښارګوټي پورې چې په مړې بحیرې باندې پروت دی، ورسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel47_verse_18.mp3', '', 1761754199, 1761754199),
(52286, 'Ezekiel 47:19', 'Ezekiel', 47, 19, 'جنوبي سرحد به د تامار نه لوېدیځ خواته د مریبوت‌قادش تر اوبو پورې او د هغه ځای نه شمال لوېدیځ خواته د مصر تر خوړه پورې او د مدیترانې تر بحیرې پورې ورسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel47_verse_19.mp3', '', 1761754199, 1761754199),
(52287, 'Ezekiel 47:20', 'Ezekiel', 47, 20, 'لوېدیځ سرحد به یې د مدیترانې بحیره وي، شمال خواته به هغه ځای ته ورسیږي چې د حمات غاښي ته مخامخ دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel47_verse_20.mp3', '', 1761754199, 1761754199),
(52288, 'Ezekiel 47:21', 'Ezekiel', 47, 21, '«دا ځمکه د خپلو قبیلو ترمنځ ووېشئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel47_verse_21.mp3', '', 1761754199, 1761754199),
(52289, 'Ezekiel 47:22', 'Ezekiel', 47, 22, 'دا به ستاسو تلپاتې ملکیت وي. کله چې دا ځمکه وېشئ، نو کوم پردي خلک چې ستاسو په منځ کې اوسیږي او دلته یې اولادونه پیدا شوي وي، نو هغوی ته به هم په دې ځمکه کې برخه ورکول کیږي. هغوی باید د اصلي اسراییلیانو په شان وګڼل شي او ملکیت باید هغوی ته د اسراییلو د قبیلو په شان ورکړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel47_verse_22.mp3', '', 1761754199, 1761754199),
(52290, 'Ezekiel 47:23', 'Ezekiel', 47, 23, 'پردي اوسېدونکي چې د کومې قبیلې سره اوسیږي، هغوی به هلته خپله برخه اخلي.» ما څښتن تعالی داسې ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel47_verse_23.mp3', '', 1761754199, 1761754199),
(52291, 'Habakkuk 1:1', 'Habakkuk', 1, 1, 'دا هغه پیغام دی چې څښتن حبقوق پیغمبر ته په رویا کې وښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk1_verse_1.mp3', '', 1761754199, 1761754199),
(52292, 'Habakkuk 1:2', 'Habakkuk', 1, 2, 'ای څښتنه، زه به ترڅو پورې تاته د مرستې دپاره فریاد کوم، خو ته ځواب نه راکوې؟ زه درته د ظلم په هکله چیغې وهم، خو ته مونږ نه ژغورې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk1_verse_2.mp3', '', 1761754199, 1761754199),
(52293, 'Habakkuk 1:3', 'Habakkuk', 1, 3, 'ته ولې ما مجبوروې چې دا بې انصافي ووینم؟ ته څنګه کولای شې چې داسې بد کارونه ووینې او هغه وزغمې؟ ګردچاپېره مې تباهي او ظلم روان دی او په هرځای کې جنګ او جګړې روانې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk1_verse_3.mp3', '', 1761754199, 1761754199),
(52294, 'Habakkuk 1:4', 'Habakkuk', 1, 4, 'هېڅوک قانون نه مراعت کوِِي او هېڅکله د انصاف څخه کار نه اخیستل کیږي. بدکاره خلک تل په محکمو کې بې‌ګناه خلکو ته ماتې ورکوي او د عدالت کولو مخه نیول کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk1_verse_4.mp3', '', 1761754199, 1761754199),
(52295, 'Habakkuk 1:5', 'Habakkuk', 1, 5, 'څښتن خپل قوم ته وویل: «خپل شاوخوا قومونو ته ګورئ او تاسو چې هرڅه وینئ، نو ډېر حیران به شئ. زه به ستاسو د ژوند په دوران کې داسې یو کار وکړم که تاسو ورڅخه خبر هم شئ، نو باور به ونه کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk1_verse_5.mp3', '', 1761754199, 1761754199),
(52296, 'Habakkuk 1:6', 'Habakkuk', 1, 6, 'زه به بابلیان چې ظالمان او بې‌رحمه خلک دي، قدرت ته ورسوم. هغوی به په ټوله نړۍ کې مخ په وړاندې روان وي او نور وطنونه به نیسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk1_verse_6.mp3', '', 1761754199, 1761754199),
(52297, 'Habakkuk 1:7', 'Habakkuk', 1, 7, 'هغوی وېره او ډار خپروي او دومره مغروره دي چې فکر کوي هر کار چې دوی یې کوي، هغه سم او قانوني دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk1_verse_7.mp3', '', 1761754199, 1761754199),
(52298, 'Habakkuk 1:8', 'Habakkuk', 1, 8, 'د هغوی اسونه د پړانګانو نه تېز دي او د وږیو لېوانو نه ظالمان دي. د هغوی اس سواران د لېرې وطنونو نه راځي او د هغوی اسونه په ځمکه باندې په تېزۍ سره روان دي. هغوی لکه د عقاب په شان غوټه وهي او په خپل ښکار باندې حمله کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk1_verse_8.mp3', '', 1761754199, 1761754199),
(52299, 'Habakkuk 1:9', 'Habakkuk', 1, 9, 'د هغوی لښکرې په بې‌رحمۍ سره مخ په وړاندې روانې وي او څنګه چې هغوی رانژدې کیږي، نو ټول ورڅخه وېریږي. د هغوی د اسیرانو شمېر د شګو په شان دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk1_verse_9.mp3', '', 1761754199, 1761754199),
(52300, 'Habakkuk 1:10', 'Habakkuk', 1, 10, 'هغوی د پاچاهانو سره سپک چلند کوي او په لوړ‌رتبه مامورینو پورې خاندي. هغوی په کومې کلا باندې نه ایساریږي، د هغې د دېوال سره د خاورو ډېرۍ جوړوي او هغه نیسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk1_verse_10.mp3', '', 1761754199, 1761754199),
(52301, 'Habakkuk 1:11', 'Habakkuk', 1, 11, 'بیا هغوی د باد په شان تېریږي او ورکیږي. هغه ګناهکار خلک دي، ځکه چې خپل قوت خپل خدای بولي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk1_verse_11.mp3', '', 1761754199, 1761754199),
(52302, 'Habakkuk 1:12', 'Habakkuk', 1, 12, 'ای څښتنه، ته له ازله زما خدای یې. ته زما سپېڅلی او ابدي خدای یې، زما څښتن خدای او زما ساتونکی یې. تا بابلیان غوره کړي دي چې د نورو په هکله قضاوت وکړي او هغوی ته دې قوت ورکړی، ترڅو نورو ته د هغوی د ګناهونو له امله سزا ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk1_verse_12.mp3', '', 1761754199, 1761754199),
(52303, 'Habakkuk 1:13', 'Habakkuk', 1, 13, 'خو ته څنګه کولای شې چې دا ټګان او بدکاره خلک وزغمې؟ ته سپېڅلی یې، نو په دې خاطر بدیو ته نه شې کتلی او ته نه شې کولای چې د خلکو بدکاري وزغمې. کله چې هغوی هغه خلک تباه کوي چې د دوی نه ډېر نېکان دي، نو بیا ولې چوپ پاتې کېږې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk1_verse_13.mp3', '', 1761754199, 1761754199),
(52304, 'Habakkuk 1:14', 'Habakkuk', 1, 14, 'ته څنګه کولای شې د خلکو سره د ماهیانو او خزندګانو په شان چې کوم مشر نه لري چې لارښوونه یې وکړي، چلند وکړې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk1_verse_14.mp3', '', 1761754199, 1761754199),
(52305, 'Habakkuk 1:15', 'Habakkuk', 1, 15, 'بابلیان خلک د ماهیانو په شان په چنګکونو رانیسي. هغوی خلک په جالونو کې راکاږي او د هغوی په نیولو باندې خوشحالي کوي!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk1_verse_15.mp3', '', 1761754199, 1761754199),
(52306, 'Habakkuk 1:16', 'Habakkuk', 1, 16, 'تر دې چې هغوی خپلو جالونو ته عبادت کوي او هغو ته قربانۍ وړاندې کوي، ځکه چې د هغوی جالونه هغوی ته دا توان ورکوي چې په عیش او عشرت کې ژوند وکړي او ښه خواړه وخوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk1_verse_16.mp3', '', 1761754199, 1761754199),
(52307, 'Habakkuk 1:17', 'Habakkuk', 1, 17, 'ایا ته هغوی ته اجازه ورکوې چې په دې ډول د تل دپاره په بې‌رحمۍ سره قومونه له منځه یوسي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/habakkuk1_verse_17.mp3', '', 1761754199, 1761754199),
(52308, 'Isaiah 29:1', 'Isaiah', 29, 1, 'ای د قربانۍ لویه ځایه، ای د قربانۍ لویه ځایه، افسوس ستا په حال! هغه ښار چې داود کلابند کړې ؤ. کال په کال خپل جشنونه او اخترونه ولمانځئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah29_verse_1.mp3', '', 1761754199, 1761754199),
(52309, 'Isaiah 29:2', 'Isaiah', 29, 2, 'خو بیا به څښتن په هغه ښار چې د «خدای د قربانۍ د لوی ځای» په نوم یادیږي، مصیبت راولي. په ټول ښار کې به ژړا او انګولا وي او هغه به لکه د قربانۍ د ځای په شان وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah29_verse_2.mp3', '', 1761754199, 1761754199),
(52310, 'Isaiah 29:3', 'Isaiah', 29, 3, 'څښتن به په هغه ښار باندې حمله وکړي او له هرې خوا به یې کلابند او د کلابندۍ برجونه او په دېوالونو باندې به یې لاره جوړه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah29_verse_3.mp3', '', 1761754199, 1761754199);